using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditorInternal;
public static class CapturePresentationWait {
 static bool enabled,editor,gpu,cpu;static double start;const string Root="Recovery/PresentationDiagnosis_20261107";
 public static object Run(){if(ProfilerDriver.deepProfiling)throw new Exception("Deep profiling must be off");enabled=ProfilerDriver.enabled;editor=ProfilerDriver.profileEditor;gpu=ProfilerDriver.profileGPU;cpu=ProfilerDriver.IsAreaEnabled(UnityEngine.Profiling.ProfilerArea.CPU);ProfilerDriver.profileEditor=true;ProfilerDriver.profileGPU=false;ProfilerDriver.SetAreaEnabled(UnityEngine.Profiling.ProfilerArea.CPU,true);ProfilerDriver.enabled=true;start=EditorApplication.timeSinceStartup;EditorApplication.update+=Finish;return "Capturing post-fix CPU waits for2 seconds";}
 static void Finish(){if(EditorApplication.timeSinceStartup-start<2)return;EditorApplication.update-=Finish;ProfilerDriver.enabled=false;try{var totals=new Dictionary<string,double>();string paths="frame,path,duration_ms\n";int n=0;double frames=0;for(int f=Math.Max(0,ProfilerDriver.lastFrameIndex-8);f<ProfilerDriver.lastFrameIndex;f++){using(var v=ProfilerDriver.GetRawFrameDataView(f,0)){if(!v.valid)continue;n++;frames+=v.frameTimeMs;var ends=new List<int>();var names=new List<string>();for(int i=0;i<v.sampleCount;i++){while(ends.Count>0&&i>=ends[ends.Count-1]){ends.RemoveAt(ends.Count-1);names.RemoveAt(names.Count-1);}string name=v.GetSampleName(i)??"";double children=0;int next=i+1;for(int c=0;c<v.GetSampleChildrenCount(i);c++){children+=v.GetSampleTimeMs(next);next+=1+v.GetSampleChildrenCountRecursive(next);}if(!totals.ContainsKey(name))totals[name]=0;totals[name]+=Math.Max(0,v.GetSampleTimeMs(i)-children);if(name.Contains("Wait")&&v.GetSampleTimeMs(i)>.5f)paths+=f+",\""+String.Join(" > ",names)+" > "+name+"\","+v.GetSampleTimeMs(i).ToString(System.Globalization.CultureInfo.InvariantCulture)+"\n";if(v.GetSampleChildrenCount(i)>0){ends.Add(i+1+v.GetSampleChildrenCountRecursive(i));names.Add(name);}}}}string summary="Main-thread profiled frames="+n+" mean_ms="+frames/Math.Max(1,n)+"\n"+String.Join("\n",totals.OrderByDescending(p=>p.Value).Take(25).Select(p=>p.Key+" self_avg_ms="+p.Value/Math.Max(1,n)));File.WriteAllText(Root+"/AC_CPU_Profile.txt",summary);File.WriteAllText(Root+"/AC_WaitPaths.csv",paths);File.WriteAllText(Root+"/CpuCapture.status","COMPLETE");}catch(Exception e){File.WriteAllText(Root+"/CpuCapture.status","ERROR "+e);}finally{ProfilerDriver.profileEditor=editor;ProfilerDriver.profileGPU=gpu;ProfilerDriver.SetAreaEnabled(UnityEngine.Profiling.ProfilerArea.CPU,cpu);ProfilerDriver.enabled=enabled;}}
}
